    "id": "common/Anchor.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { Ref } from \"./Ref\";\n\n/** 空间关系所参照的世界锚点 */\n\nexport type Anchor = {\n  /** 以当前用户输入提交时的位置和朝向为锚点；任务期间不随玩家移动而改变。消费新的补充输入时更新。实时位置请调用 tools.spatial.viewer()；无活动输入时使用实时位姿。它不是图片拍摄位姿；图片选点使用 pick 返回的位置。只读取位姿，不移动玩家。 */\n  kind: \"viewer\";\n} | {\n  kind: \"world-ref\";\n  /** world.query 或修改 API 返回的稳定世界引用。 */\n  ref: Ref;\n} | {\n  kind: \"selection\";\n  /** world.query 返回或命名保存的选择标识。 字符长度：1 到 160。 */\n  selectionId: string;\n} | {\n  kind: \"position\";\n  /** 明确世界 x 坐标。 */\n  x: number;\n  /** 明确世界 y 坐标；省略时由 placement 解析。 */\n  y?: number;\n  /** 明确世界 z 坐标。 */\n  z: number;\n};\n",
