    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\n/** 相对于锚点的空间关系 */\n\nexport type Relation = {\n  /** 位于锚点本身。 */\n  kind: \"at\";\n} | {\n  /** 位于锚点水平朝向正前方。 */\n  kind: \"front\";\n  /** 正前方的精确水平距离，单位为米；用户只说“面前”或“前方”时必须省略并使用默认 20 米，用户明确距离时必须原样填写。 取值范围：0.5 到 5000。 */\n  distanceMetres?: number;\n} | ({\n  kind: \"behind\" | \"left\" | \"right\";\n  /** 与锚点的距离，单位为米。 取值范围：0.5 到 5000。 */\n  distanceMetres: number;\n}) | {\n  kind: \"near\";\n  /** 期望距离，单位为米。 取值范围：0.5 到 5000。 */\n  preferredDistanceMetres: number;\n} | {\n  kind: \"around\";\n  /** 圆形区域半径，单位为米。 取值范围：0.5 到 2000。 */\n  radiusMetres: number;\n} | {\n  kind: \"offset\";\n  /** 锚点局部前后偏移，负值向后；普通‘面前’关系应使用 front。 取值范围：-5000 到 5000。 */\n  forwardMetres: number;\n  /** 锚点局部左右偏移，负值向左。 取值范围：-5000 到 5000。 */\n  rightMetres: number;\n  /** 上下偏移，负值向下。 取值范围：-1000 到 1000。 */\n  upMetres?: number;\n};\n",
