    "id": "common/Target.d.ts",
    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { Anchor } from \"./Anchor\";\nimport type { Relation } from \"./Relation\";\n\n/** 所有导航与地景能力共享的空间语言；地景 Tool 只能读取 viewer Pose。贴地、避障、避水等 placement 必须写在 target.placement，不能放在 Tool 顶层 */\n\nexport type Target = {\n  /** 空间关系的参照物。 */\n  anchor: Anchor;\n  /** 关系向量使用的坐标系；anchor-local 跟随锚点朝向，world 使用世界轴；省略时为 anchor-local。front 始终使用锚点的水平方向，不受 frame 覆盖。 */\n  frame?: \"world\" | \"anchor-local\";\n  /** 默认 surface；对象通常使用 center 或 bounds-nearest。 */\n  origin?: \"feet\" | \"eyes\" | \"center\" | \"surface\" | \"bounds-nearest\" | \"bounds-center\";\n  /** 目标相对于锚点的位置关系。 */\n  relation: Relation;\n  /** 贴地、贴水、碰撞、坡度和水域约束；省略时默认贴合地形。 */\n  placement?: {\n    /** 高度贴合规则：terrain 贴地、water-surface 贴水面、none 保留锚点高度。 */\n    snapTo: \"terrain\" | \"water-surface\" | \"none\";\n    /** 对象碰撞规则；avoid 避开已有对象，allow 允许重叠；省略时由调用方使用安全默认值。 */\n    collision?: \"avoid\" | \"allow\";\n    /** 允许的最大地表坡度，单位为度；省略时不限制坡度。 取值范围：0 到 90。 */\n    maxSlope?: number;\n    /** true 要求目标避开水域；省略或 false 时不施加避水约束。 */\n    avoidWater?: boolean;\n    /** true 要求目标位于实时真实水域；省略或 false 时不要求水域。 */\n    requireWater?: boolean;\n  };\n};\n",
    "imports": [
      "common/Anchor.d.ts",
      "common/Relation.d.ts"
    ],
    "toolNames": []
