    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\nimport type { EnvironmentUpdateResult } from \"../common/EnvironmentUpdateResult\";\nimport type { Season } from \"../common/Season\";\ndeclare global {\n  namespace AgentTools {\n    interface TimeApi {\n      /**\n       * 调用入口：await tools.time.update(input)\n       * 修改世界时间、季节或二者，默认平滑过渡；时间由引擎逐帧向前推进，不需要脚本循环。\n       * @param input - 至少包含 timeHours 或 season，可配置过渡和环境光等待。\n       * @returns 返回规范化请求和草稿目标状态，并未开始过渡。execute 提交后才执行过渡；waitForIbl 控制额外等待环境光。以 execute.receipt 判断提交，提交后的过渡失败记录在 runtimeErrors，不撤销编辑数据。\n       */\n      update(input: {\n        /** 目标世界时刻，0 和 24 都表示午夜。 取值范围：0 到 24。 */\n        timeHours: number;\n        /** 明确指定的起点时刻；省略则从当前时刻开始。指定后先设置起点，再向目标过渡。 取值范围：0 到 24。 */\n        fromTimeHours?: number;\n        season?: Season;\n        /** 现实中的过渡秒数。用户未指定时长时省略，默认平滑过渡 5 秒；指定时长时按其要求传入。只有用户明确要求瞬切或不要过渡时才传 0，‘变成晚上’或‘切到白天’不表示瞬切。时间向前连续变化，6 到 24 经过中午和黄昏，23 到 1 跨午夜。 取值范围：0 到 60。 */\n        transitionDuration?: number;\n        /** 是否等待环境光烘焙发布，省略时为 true。 */\n        waitForIbl?: boolean;\n      } | {\n        /** 目标世界时刻，0 和 24 都表示午夜。 取值范围：0 到 24。 */\n        timeHours?: number;\n        season: Season;\n        /** 现实中的过渡秒数。用户未指定时长时省略，默认平滑过渡 5 秒；指定时长时按其要求传入。只有用户明确要求瞬切或不要过渡时才传 0，‘变成晚上’或‘切到白天’不表示瞬切。时间向前连续变化，6 到 24 经过中午和黄昏，23 到 1 跨午夜。 取值范围：0 到 60。 */\n        transitionDuration?: number;\n        /** 是否等待环境光烘焙发布，省略时为 true。 */\n        waitForIbl?: boolean;\n      }): Promise<EnvironmentUpdateResult>;\n    }\n  }\n}\n\nexport {};\n",
