    "source": "// AUTO-GENERATED by generate-agent-contracts.ts from executable Zod contracts.\n// Do not edit this file directly.\n\nimport type { AgentToolsDeclaration } from \"../common/AgentTools\";\nimport type { Season } from \"../common/Season\";\ndeclare global {\n  namespace AgentTools {\n    interface AtmosphereApi {\n      /**\n       * 调用入口：await tools.atmosphere.get()\n       * 读取当前天空颜色、风、雨、雪、雷、云、雾和环境光状态。\n       * @returns 当前天象与环境光状态。\n       */\n      get(): Promise<{\n        phase: string;\n        /** 玩家语义的完整天象状态；字段均位于 environment 顶层，不使用 wind、rain 或 lightning 子对象。 */\n        environment: {\n          /** 天空染色的 sRGB 三通道整数 0 到 255；例如紫色 [180,80,255]，null 恢复默认昼夜天空。染色立即生效并保持到当前世界销毁或显式恢复；保留时间、天气与太阳/月亮，实际亮度受昼夜光照影响。 */\n          skyColorRgb?: [number, number, number] | null;\n          /** 当前季节。 */\n          season: Season;\n          /** 季节过渡进度，1 表示已完成。 */\n          seasonTransitionProgress: number;\n          /** 当前降水摘要，例如 none、rain:1.00 或 snow:0.50。 */\n          precipitation: string;\n          /** 当前降雨强度。 */\n          rainIntensity: number;\n          /** 当前降雪强度。 */\n          snowIntensity: number;\n          /** 当前云层覆盖。 */\n          cloudCoverage: number;\n          /** 当前雾强度。 */\n          fogIntensity: number;\n          /** 当前配置的持续风速，单位为米每秒；不包含瞬时阵风波动。 */\n          windSpeed: number;\n          /** 风力归一化强度。 */\n          windIntensity: number;\n          /** 当前实际风吹向的世界水平航向，度：0 为 -Z，90 为 +X，-90 为 -X。过渡中可不同于目标；静风时保留最后有效方向，不表示仍有风。 */\n          windDirectionDegrees: number;\n          /** 当前阵风强度。 */\n          windGustiness: number;\n          /** 当前乱流程度。 */\n          windTurbulence: number;\n          /** 当前闪电频率。 */\n          lightningFrequency: number;\n          /** 当前闪电强度。 */\n          lightningIntensity: number;\n        };\n        ibl: {\n          phase: string;\n          progress: number;\n          bakingEnabled: boolean;\n        };\n      }>;\n    }\n  }\n}\n\nexport {};\n",
